"use client";

import { useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { createNewTask } from "@/app/actions/task-actions";
import { Loader2 } from "lucide-react";

// Hata almaman için bu obje mutlaka fonksiyonun DIŞINDA tanımlanmalı
const SCRUM_TEMPLATES = {
  DAILY_SCRUM: {
    title: "Daily Scrum",
    fields: [
      "Wat is klaar sinds vorige Daily Scrum? ",
      "Werkt het team volgens planning? (Ja/Nee + Reden) ",
      "Zijn er problemen / obstakels? "
    ]
  },
  SPRINT_PLANNING: {
    title: "Sprint Planning",
    fields: [
      "Sprint Backlog (Grote stappen) ",
      "To Do lijst (Concrete activiteiten) ",
      "Sprint oplevering (Wat & Wanneer) ",
      "Definition of Done "
    ]
  },
  RETROSPECTIVE: {
    title: "Sprint Retrospective",
    fields: [
      "Wat ging allemaal goed? ",
      "Wat kan beter? ",
      "Actiepunt voor volgende Sprint "
    ]
  },
  REVIEW: {
    title: "Sprint Review",
    fields: [
      "Wat heb jij gemaakt/geleerd? ",
      "Wat beheers jij nog niet voldoende? ",
      "Hoe ga jij dit verhelpen? (Actiepunten) "
    ]
  }
};

export default function TaskFormModal({ open, setOpen }: any) {
  const [selectedTemplate, setSelectedTemplate] = useState<string>("");
  const [formData, setFormData] = useState<any>({});
  const [sprintNr, setSprintNr] = useState("1");
  const [loading, setLoading] = useState(false);

  const handleSave = async () => {
    if (!selectedTemplate) return alert("Kies bir template!");
    
    setLoading(true);
    // Verileri JSON string olarak kaydediyoruz ki sonra Notion gibi okuyabilelim
    const contentString = JSON.stringify({
      team: "WorkSpace [cite: 5, 26]",
      klas: "2024-ST-ST-L-NEXT-2 [cite: 3, 15, 25]",
      templateData: formData
    });

    const result = await createNewTask(
      `${SCRUM_TEMPLATES[selectedTemplate as keyof typeof SCRUM_TEMPLATES].title} - Sprint ${sprintNr}`,
      contentString
    );

    if (result.success) {
      setOpen(false);
      setFormData({});
      setSelectedTemplate("");
    }
    setLoading(false);
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogContent className="bg-[#0E153A]/95 border border-teal-400/30 text-white max-w-3xl overflow-y-auto max-h-[90vh] backdrop-blur-xl rounded-[2rem]">
        <DialogHeader>
          <DialogTitle className="text-3xl font-black bg-gradient-to-r from-teal-300 to-fuchsia-400 bg-clip-text text-transparent uppercase">
            Nieuw Scrum Document
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-6 mt-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <label className="text-[10px] text-teal-400 font-bold uppercase tracking-widest ml-1">Template</label>
              <Select onValueChange={(val) => setSelectedTemplate(val)}>
                <SelectTrigger className="bg-black/40 border-teal-400/20 h-12 rounded-xl">
                  <SelectValue placeholder="Kies een template" />
                </SelectTrigger>
                <SelectContent className="bg-[#0E153A] border-teal-400/30 text-white">
                  <SelectItem value="DAILY_SCRUM">Daily Scrum</SelectItem>
                  <SelectItem value="SPRINT_PLANNING">Sprint Planning</SelectItem>
                  <SelectItem value="REVIEW">Sprint Review</SelectItem>
                  <SelectItem value="RETROSPECTIVE">Sprint Retrospective</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <label className="text-[10px] text-teal-400 font-bold uppercase tracking-widest ml-1">Sprint Nr</label>
              <Input 
                type="number" 
                value={sprintNr} 
                onChange={(e) => setSprintNr(e.target.value)}
                className="bg-black/40 border-teal-400/20 h-12 rounded-xl"
              />
            </div>
          </div>

          {selectedTemplate && (
            <div className="space-y-5 animate-in fade-in slide-in-from-top-4 duration-500">
              <div className="p-4 rounded-xl bg-teal-400/5 border border-teal-400/10 mb-4">
                <p className="text-xs text-teal-400/70 italic font-medium">
                  Team: WorkSpace | Klas: 2024-ST-ST-L-NEXT-2 [cite: 3, 5]
                </p>
              </div>
              
              {SCRUM_TEMPLATES[selectedTemplate as keyof typeof SCRUM_TEMPLATES].fields.map((field) => (
                <div key={field} className="space-y-2">
                  <label className="text-xs font-bold text-teal-100/80 ml-1">{field}</label>
                  <Textarea 
                    placeholder="Vul hier je antwoord in..."
                    className="bg-black/40 border-teal-400/20 min-h-[100px] rounded-xl focus:border-fuchsia-400 transition-all"
                    onChange={(e) => setFormData({...formData, [field]: e.target.value})}
                  />
                </div>
              ))}
            </div>
          )}

          <Button 
            onClick={handleSave} 
            disabled={!selectedTemplate || loading}
            className="w-full bg-gradient-to-r from-teal-400 to-fuchsia-400 text-[#070B24] font-black h-14 rounded-2xl shadow-lg hover:scale-[1.02] active:scale-95 transition-all"
          >
            {loading ? <Loader2 className="animate-spin" /> : "DOCUMENT OPSLAAN"}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}